      var sa=Math.PI/4+s*Math.PI/2;
      FR3(x+Math.cos(sa)*I[3]*0.36, y+1.8, z+Math.sin(sa)*I[3]*0.36, 3.4, rr(11,17), 3.4, sa, col);
