      lifeDhowGearMesh.setColorAt(i*LIFE_DHOW_GEAR_PER+g, gearCol.set(hex).convertSRGBToLinear());

      gearP.set(LIFE_FISH_BOATS[i].x, SEA, LIFE_FISH_BOATS[i].z);
